const courses = [
  { id: 1, name: 'HTML', chapters: 22 },
  { id: 2, name: 'CSS', chapters: 27 },
  { id: 3, name: 'JavaScript', chapters: 36 },
];

function CourseList() {
  return (
    <ul>
      {courses.map((course) => (
        <li key={course.id}>
          {course.name} — {course.chapters} chapters
        </li>
      ))}
    </ul>
  );
}

function StudentCard({ name, grade }) {
  return (
    <div className="card">
      <h3>{name}</h3>
      <p>Grade: {grade}</p>
    </div>
  );
}

function StudentList({ students }) {
  return (
    <div>
      {students.map((student) => (
        <StudentCard
          key={student.id}
          name={student.name}
          grade={student.grade}
        />
      ))}
    </div>
  );
}
